class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2 != 0:
            return False

        target = total // 2
        dp = set([0])

        for n in nums:
            new_dp = set()
            for s in dp:
                if s + n == target:
                    return True
                new_dp.add(s + n)
            dp = dp | new_dp

        return target in dp

